// POSIX/System V setpgrp(): 
// Sets PGID of the calling process to its PID.
// Equivalent to setpgid(0, 0)
pid_t current_pid = getpid();
int status = setpgrp(); 

if (status == -1) {
    // EACCES: Child had already called execve(2)
    // EPERM: Attempt to move process between sessions/groups
    perror("setpgrp failed");
}

